INSERT INTO `effect_subcategories` (`id`, `dicecount`, `dicesize`, `name`, `note`, `typeid`) VALUES
                                                                                                 (1,	2,	6,	'Mutation mineure',	'La mutation magique survient en cinq minutes. Pour se débarrasser d\'une mutation, lui ou un allié, un mage peut essayer un dispel magic, une seule fois.\nEn cas d\'échec, il convient de se rendre dans une clinique de mages, à Glargh ou bien à Waldorg. Le résultat n\'est pas garanti.\nDans le cas d\'une mutation non visible immédiatement, le MJ doit se débrouiller pour permettre au héros de découvrir sa mutation, cela peut prendre du temps.',	1),
                                                                                                 (2,	1,	20,	'Mutation majeure',	'La mutation magique survient en cinq minutes. Pour se débarrasser d\'une mutation, lui ou un allié, un mage peut essayer un dispel magic, une seule fois.\nEn cas d\'échec, il convient de se rendre dans une clinique de mages, à Glargh ou bien à Waldorg. Le résultat n\'est pas garanti.\nDans le cas d\'une mutation non visible immédiatement, le MJ doit se débrouiller pour permettre au héros de découvrir sa mutation, cela peut prendre du temps.',	1),
                                                                                                 (3,	1,	20,	'Folie',	'Table que vous pouvez appliquer en cas d\'événement provoquant la folie d\'un personnage : sortilège raté, échec critique au courage, malédiction...\nVous devrez donc apporter les modifications pendant la durée de l\'effet de folie et aussi modifier le rôleplay !\n\nDurée : dans le cas où la durée de l\'effet de folie n\'est pas précisée, comptez 1D20+10 heures ou 2D20 heures (choix MJ)',	2),
                                                                                                 (4,	0,	0,	'Conséquences blessures graves',	'',	2),
                                                                                                 (5,	1,	20,	'Poison',	'Les effets de ces poisons sont valables sur les humains ou humanoïdes de taille standard. Ils n\'ont pas forcément le même effet sur les monstres...\nIls peuvent aussi bien ne pas avoir d\'effet du tout ! Pour tous les cas étranges, c\'est le MJ qui décide.',	3),
                                                                                                 (6,	0,	0,	'Antidote',	'Les antidotes agissent 4 secondes après inoculation par intraveineuse et 20 secondes après ingestion.',	3),
                                                                                                 (7,	0,	0,	'Autres',	'',	5),
                                                                                                 (8,	0,	0,	'Généraliste',	NULL,	4),
                                                                                                 (9,	0,	0,	'Tzinntch',	NULL,	4),
                                                                                                 (10,	0,	0,	'Slanoush',	NULL,	6),
                                                                                                 (11,	0,	0,	'Khornettoh',	NULL,	6),
                                                                                                 (12,	0,	0,	'Necromancie',	NULL,	4),
                                                                                                 (13,	0,	0,	'Maladie',	'Les chances d\'attraper une maladie sont souvent données en pourcentage. Pour savoir si quelqu\'un attrape ou non une maladie, vous\r\npouvez lancer (ou faire lancer au héros) un D20 et appliquer les règles pifométriques suivantes :\r\n* 10% : il faut faire 19 ou 20\r\n* 20% : il faut faire de 17 à 20\r\n* 30% : il faut faire de 15 à 20\r\n* 40% : il faut faire de 13 à 20\r\n* 50% : il faut faire de 11 à 20\r\n* 60% : il faut faire de 8 à 20\r\n* 70% : il faut faire de 6 à 20\r\n* 80% : il faut faire de 4 à 20\r\n* 90% : il faut faire de 3 à 20\r\n* sur 1 ou 2 la maladie est toujours évitée',	5),
                                                                                                 (14,	0,	0,	'Combat',	NULL,	4),
                                                                                                 (15,	0,	0,	'Effet instumental',	NULL,	5);
INSERT INTO `effect_types` (`id`, `name`) VALUES
                                              (1,	'Mutation'),
                                              (2,	'Critique'),
                                              (3,	'Poison'),
                                              (4,	'Magie'),
                                              (5,	'Autre'),
                                              (6,	'Prodige');
INSERT INTO `gods` (`id`, `displayname`, `description`, `techname`) VALUES
                                                                        (1,	'Adathie',	'Justice et Saucisse. Non violent sauf si vous êtes coupable (de n\'importe quoi, d\'ailleurs)',	'ADATHIE'),
                                                                        (2,	'Dlul',	'Sommeil et Ennui. Calme (sauf si vous dérangez la sieste). Leur hostilité à l\'égard d\'Oboulos est vite tempérée par la dépense\nénergétique générée par ladite hostilité.',	'DLUL'),
                                                                        (3,	'Khornettoh',	'Violence. Violent. (ça vous étonne?)',	'KHORNETTOH'),
                                                                        (4,	'Slanoush',	'Perversion et mystère. Non violent, mais très jaloux, ils ne doivent pas favoriser un autre culte que le leur par leurs actions. ',	'SLANOUSH'),
                                                                        (5,	'Tzinntch',	'Magie Noire et Maléfices. Violent, déteste tout le monde. Khornettoh est à la rigueur apprécié tant que le bourrin soit utile.',	'TZINNTCH'),
                                                                        (6,	'Youclidh',	'Non violent, il s\'opposera aux violents. (un peu paradoxal, mais ils disent « soigner le mal par le mal »)',	'YOUCLIDH'),
                                                                        (7,	'Braav\'',	'Non-Violent, Loyal Bon. Il vous demandera la permission avant de vous attaquer, s\'excusera pour le désagrément et se sentira obligé\nde respecter une demande de pourparlers ou de trève. ',	'BRAAV'),
                                                                        (8,	'Niourgl',	NULL,	'NIOURGL');
INSERT INTO `handicaps` (`id`, `diceRoll`, `name`, `data`) VALUES
                                                         ('431715f5-d259-5f21-967d-c62374ce13c5',	1,	'Coup de chance',	'{\"effect\": \"Vous n’avez pas de handicap\"}'),
                                                         ('443cb01e-ad89-592f-befc-b7db470b0865',	2,	'Ablutophobie',	'{\"effect\": \"EC+1 sur les épreuves de NAGER\"}'),
                                                         ('0325bd82-dc57-5db7-afe5-77e68fd1b3f6',	3,	'Achluophobie',	'{\"effect\": \"EC+1 dans un environnement sombre\"}'),
                                                         ('fee2e51f-52cc-5723-b8e8-11fb9fffae7e',	4,	'Acrophobie',	'{\"effect\": \"EC+1 à toutes les épreuves en hauteur (montagne, colline, …)\"}'),
                                                         ('7548d4ab-11d9-5e10-a925-ea9660ba3a61',	5,	'Immuno-déficient',	'{\"effect\": \"Augmente de 20% le risque de contracter une maladie\"}'),
                                                         ('78d134ed-0ce6-54eb-b029-5d0423e8b03e',	6,	'Alcoolique reconnu',	'{\"condition\": \"Appel du tonneau\", \"effect\": \"Malus de -2 aux épreuves d’APPEL DU TONNEAU\"}'),
                                                         ('d949ac5a-e22e-5534-bfd5-1fb194ae6c7d',	7,	'Alektorophobie',	'{\"effect\": \"Malus de -3 en COU contre les poulets, dindes, faisans, pintades...\"}'),
                                                         ('f3c127b5-d639-55ef-a1ba-7076b3d2023c',	8,	'Anthrophobie',	'{\"effect\": \"Malus de -3 en COU lorsque le personnage est entouré de fleurs\"}'),
                                                         ('6ed3a44a-a9ce-5e09-a9bd-f524f2880e6e',	9,	'Anxiété mutique',	'{\"effect\": \"Le héros est frappé de mutisme s’il échoue à une épreuve de COU lors d’une situation de stress\"}'),
                                                         ('fb8e906e-00fe-50b4-808c-e445e712d6c2',	10,	'Appel du vide',	'{\"effect\": \"Malus de -1 aux épreuves si proche du vide (falaise, escalier, précipice…)\"}'),
                                                         ('4916e1d9-cec4-533b-8e9c-e7875c9da7ed',	11,	'Arachnophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 contre des arachnides\"}'),
                                                         ('4344d59b-f1bb-5853-95ab-ea2404eb9265',	12,	'Arithmophobie',	'{\"condition\": \"Spécialité Thermodynamique\", \"effect\": \"EC+1 sur les sorts de Thermodynamique\"}'),
                                                         ('ffc82f62-a4c4-57e3-ba87-7ef7d140842c',	13,	'Astraphobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 lors d’un orage\"}'),
                                                         ('90cb22e3-09fe-52c1-a068-a1326a392c8e',	14,	'Automysophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 lorsque le héros est sale\"}'),
                                                         ('64af4b7f-86a6-57e1-b057-d5ae2cc9367b',	15,	'Aviophobie',	'{\"effect\": \"Épreuve de COU-3 lors d’une situation de vol ou de lévitation\"}'),
                                                         ('ef64f6be-f232-5d30-988c-dd644694b8c3',	16,	'Bactériophobie',	'{\"effect\": \"EC+3 contre les serviteurs de Niourgl\"}'),
                                                         ('51ff06d5-8955-5012-ac2e-693a44e705b8',	17,	'Bafouillage',	'{\"condition\": \"Fariboles\", \"effect\": \"EC+3 sur une épreuve de FARIBOLES\"}'),
                                                         ('6f10b989-ae78-57ce-bc2d-c992891b9d5e',	18,	'Bibliophobie',	'{\"effect\": \"Malus de -3 en COU dans une bibliothèque, librairie, …\"}'),
                                                         ('ca3617ce-3247-5720-9bc3-826a52e8a23e',	19,	'Botanophobie',	'{\"effect\": \"Malus de -3 en COU contre les plantes\"}'),
                                                         ('371523cb-2ee6-5ef7-a13a-b09192f20bbe',	20,	'Bricolage foireux',	'{\"condition\": \"Bricolo du dimanche\", \"effect\": \"EC+2 sur une épreuve de BRICOLO DU DIMANCHE\"}'),
                                                         ('661abf8b-3474-5bd5-a05f-d11096d47516',	21,	'C’est mon mien à moi',	'{\"condition\": \"Radin\", \"effect\": \"Malus de -2 aux épreuves de RADIN pour partager quelque chose\"}'),
                                                         ('4848a23a-55ca-5c4e-a404-0593384c6ddf',	22,	'Candeur elfique',	'{\"condition\": \"Elfe\", \"effect\": \"Malus de -2 en INT pour détecter un piège\"}'),
                                                         ('bbf4aca0-a105-5b95-a3bf-a44f657d6ab3',	23,	'Casse-croûte sur pattes',	'{\"condition\": \"Attire les monstres\", \"effect\": \"Toujours ciblé en premier, même si d’autres personnages ont la compétence ATTIRE LES MONSTRES\"}'),
                                                         ('2b6b6dd6-2736-5a08-8d37-175f35a29861',	24,	'Castelophobie',	'{\"effect\": \"EC+1 à toutes les épreuves dans un château\"}'),
                                                         ('51c7504e-6fbf-5725-b7b5-f23c125ed479',	25,	'Cheveux sur la langue',	'{\"condition\": \"Intimidation\", \"effect\": \"EC+3 sur une épreuve d’INTIMIDATION\"}'),
                                                         ('9a2bdaa3-c64c-5c4e-9df6-0028c8c34f21',	26,	'Chionophobie',	'{\"effect\": \"EC+2 à toutes les épreuves en présence de neige\"}'),
                                                         ('fc1c0010-ccb2-54ee-a6fb-11e3562f99fb',	27,	'Chlorophobie',	'{\"effect\": \"EC+3 aux actions contre des plantes\"}'),
                                                         ('1b8da217-9dd2-5f88-9d69-b29cce4cd8a2',	28,	'Climacophobie',	'{\"effect\": \"Épreuve de COU nécessaire pour emprunter un escalier\"}'),
                                                         ('481ef8ee-31e0-540e-a479-2363e0c0f1b6',	29,	'Coïmetrophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 dans un cimetière\"}'),
                                                         ('15c9de43-60a7-5a8c-a948-7785b4012d19',	30,	'Couacophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 contre des canards et oies\"}'),
                                                         ('0c43c1f3-1a27-5fbe-a638-6273b597376a',	31,	'Courage dans les chaussettes',	'{\"effect\": \"COU-5 et malus -1 à toutes les épreuves si les ennemis sont deux fois plus nombreux que le groupe\"}'),
                                                         ('ca9e7de0-f2bb-5406-ab83-3b5ecc36e884',	32,	'Crétinophobie',	'{\"effect\": \"Malus de -3 en COU contre les ennemis ayant TÊTE VIDE\"}'),
                                                         ('9295a494-d9a9-58c5-8fda-3035139e3da0',	33,	'Cuniculophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 contre les lapins\"}'),
                                                         ('2f5d7019-e9d9-5ea3-affd-bf4ae18e9752',	34,	'Cynophobie',	'{\"effect\": \"Malus de -3 en COU et EC+1 contre les canidés (loup, chien, coyote…)\"}'),
