                                                                                                                                                   (17,	'Cendres de vierge tuee par un dragon',	'{\"icon\": {\"name\": \"powder\", \"color\": \"#fb9fda\", \"rotation\": 0}, \"price\": 100, \"space\": \"négligeable\", \"diceDrop\": 89, \"throwable\": 0, \"description\": \"Inutile de vous expliquer pourquoi cet ingrédient est aussi rare que cher !\", \"quantifiable\": 1, \"availableLocation\": \"magasin pour mage\"}',	'Cendres de vierge tuée par un dragon',	NULL,	'official',	NULL,	NULL,	'5c3f4d0b-0b20-11ea-bd72-4c72b9310a53'),
