                                                                                                           (1,	'',	'Récupération',	'',	'',	1),
                                                                                                           (2,	'',	'Lames courtes',	'',	'',	1),
                                                                                                           (3,	'',	'Lames 1 main',	'ces armes à 1 main sont utilisées à 2 mains par les petites créatures (Nains, gobelins, semi-hommes...)',	'',	1),
                                                                                                           (4,	'',	'Lames 2 mains',	'ces armes longues et lourdes sont inutilisables par les Nains et petites créatures (gobelins, semi-hommes...), sauf indication contraire',	'',	1),
                                                                                                           (5,	'',	'Haches 1 main',	'Sauf avis contraire, ces armes à 1 main sont à 2 mains pour les Nains, car souvent trop longues',	'',	1),
                                                                                                           (6,	'',	'Haches de jet',	'',	'',	1),
                                                                                                           (7,	'',	'Haches 2 mains',	'ces armes longues et lourdes sont inutilisables par les Nains et petites créatures (gobelins, semi-hommes...)',	'',	1),
